PRAGMA foreign_keys=ON;
CREATE TABLE InvestorProfile(investor_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, risk_tolerance TEXT NOT NULL CHECK(risk_tolerance IN ('Conservative','Balanced','Growth')), created_at TEXT NOT NULL);
CREATE TABLE Portfolio(portfolio_id TEXT PRIMARY KEY, investor_id TEXT NOT NULL REFERENCES InvestorProfile, base_currency TEXT NOT NULL CHECK(base_currency='INR'), account_value REAL NOT NULL CHECK(account_value>0), cash_balance REAL NOT NULL CHECK(cash_balance>=0), lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN ('ACTIVE','CLOSED')), created_at TEXT NOT NULL);
CREATE TABLE Instrument(instrument_id TEXT PRIMARY KEY, ticker TEXT UNIQUE NOT NULL, name TEXT NOT NULL, asset_class TEXT NOT NULL CHECK(asset_class IN ('INDIAN_EQUITY','GLOBAL_EQUITY','GOVT_BONDS','GOLD','CASH')), currency TEXT NOT NULL CHECK(currency='INR'), eligible INTEGER NOT NULL CHECK(eligible IN (0,1)), lifecycle_state TEXT NOT NULL);
CREATE TABLE Holding(holding_id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES Portfolio, instrument_id TEXT NOT NULL REFERENCES Instrument, quantity REAL NOT NULL CHECK(quantity>=0), as_of TEXT NOT NULL, lifecycle_state TEXT NOT NULL, UNIQUE(portfolio_id,instrument_id));
CREATE TABLE MarketPrice(price_id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES Instrument, price_date TEXT NOT NULL, close REAL NOT NULL CHECK(close>0), currency TEXT NOT NULL CHECK(currency='INR'), stale_flag INTEGER NOT NULL CHECK(stale_flag IN (0,1)), UNIQUE(instrument_id,price_date));
CREATE TABLE TargetAllocation(target_id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES Portfolio, asset_class TEXT NOT NULL, target_pct REAL NOT NULL CHECK(target_pct>=0 AND target_pct<=100), effective_from TEXT NOT NULL, effective_to TEXT, UNIQUE(portfolio_id,asset_class,effective_from));
CREATE TABLE FeeSchedule(fee_id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES Portfolio, fee_rate REAL NOT NULL CHECK(fee_rate>=0), minimum_fee REAL NOT NULL CHECK(minimum_fee>=0), maximum_fee REAL NOT NULL CHECK(maximum_fee>=0), effective_from TEXT NOT NULL, effective_to TEXT);
CREATE TABLE "Constraint"(constraint_id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES Portfolio, minimum_trade REAL NOT NULL CHECK(minimum_trade>=0), drift_threshold REAL NOT NULL CHECK(drift_threshold>=0), exclude_ineligible INTEGER NOT NULL CHECK(exclude_ineligible IN (0,1)), max_turnover_pct REAL NOT NULL CHECK(max_turnover_pct>=0), effective_from TEXT NOT NULL, effective_to TEXT);
CREATE TABLE RebalanceProposal(proposal_id TEXT PRIMARY KEY, portfolio_id TEXT NOT NULL REFERENCES Portfolio, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('READY','REVIEW','ON_TARGET')), exception_codes TEXT NOT NULL, total_value REAL NOT NULL CHECK(total_value>=0), estimated_fees REAL NOT NULL CHECK(estimated_fees>=0));
CREATE TABLE Trade(trade_id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES RebalanceProposal, portfolio_id TEXT NOT NULL REFERENCES Portfolio, instrument_id TEXT NOT NULL REFERENCES Instrument, side TEXT NOT NULL CHECK(side IN ('BUY','SELL')), quantity REAL NOT NULL CHECK(quantity>=0), notional REAL NOT NULL CHECK(notional>=0), estimated_fee REAL NOT NULL CHECK(estimated_fee>=0), status TEXT NOT NULL CHECK(status IN ('PROPOSED','BLOCKED','NO_ACTION')), reason_code TEXT NOT NULL);
CREATE TABLE PostTradeAllocation(allocation_id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES RebalanceProposal, asset_class TEXT NOT NULL, current_pct REAL NOT NULL CHECK(current_pct>=0), target_pct REAL NOT NULL CHECK(target_pct>=0 AND target_pct<=100), projected_pct REAL NOT NULL CHECK(projected_pct>=0), drift_pct REAL NOT NULL, UNIQUE(proposal_id,asset_class));
CREATE INDEX idx_holding_portfolio ON Holding(portfolio_id);
CREATE INDEX idx_price_instrument_date ON MarketPrice(instrument_id,price_date DESC);
CREATE INDEX idx_proposal_portfolio ON RebalanceProposal(portfolio_id,created_at DESC);
CREATE INDEX idx_posttrade_proposal ON PostTradeAllocation(proposal_id);
